#pragma once

// 文件管理页面随程序编译，避免运行时依赖额外的静态文件路径。
static const char FILE_PAGE[] = R"PAGE(<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>文件管理</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f3f5f7;color:#34434f;font:14px system-ui,-apple-system,"Segoe UI",sans-serif}button,.choose{font:inherit;cursor:pointer}main{min-height:100vh;display:flex;flex-direction:column}.topbar{display:flex;align-items:center;gap:14px;padding:12px 20px;background:#edf3f9;border-bottom:1px solid #c8d4df}.topbar h1{font-size:17px;color:#174e7e;margin:0}.address{flex:1;background:white;border:1px solid #c8d4df;padding:9px 12px;color:#526474}.toolbar{display:flex;align-items:center;gap:10px;padding:10px 20px;background:#fafbfc;border-bottom:1px solid #d5dde4}button,.choose{border:1px solid #bfcbd6;background:#fff;color:#344c62;border-radius:3px;padding:7px 14px}.choose{display:inline-block;background:#17659c;border-color:#17659c;color:white}button:hover{background:#eef4f9}.layout{display:grid;grid-template-columns:210px minmax(0,1fr);flex:1}.sidebar{background:#fafbfc;border-right:1px solid #d8e0e7;padding:20px 12px}.sidebar h2{margin:0 8px 14px;color:#7b8b99;font-size:12px;font-weight:600}.selected{background:#176095;color:white;border-radius:3px;padding:10px 12px}.content{background:white;padding:22px 26px;min-width:0}.heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:15px}.heading h2{margin:0;font-size:17px;color:#284a68}.badge,.hint{color:#81909d;font-size:12px}.columns{display:grid;grid-template-columns:minmax(0,1fr) 110px 52px;padding:10px 12px;border-top:1px solid #d9e2ea;border-bottom:1px solid #c8d4df;color:#245778;background:#fafcfe}.file{display:grid;grid-template-columns:30px minmax(0,1fr) auto;gap:8px;align-items:center;padding:11px 12px;border-bottom:1px solid #e6ebef}.file:hover{background:#f5f9fc}.icon{color:#e6a024;font-size:18px}.details{display:grid;grid-template-columns:minmax(0,1fr) 110px;gap:10px;align-items:center;min-width:0}.name{overflow-wrap:anywhere}.size{color:#71808d}.download{color:#16639b;text-decoration:none}.download:hover{text-decoration:underline}.muted{padding:30px 12px;color:#8794a1}.upload-info{margin-left:auto;color:#81909d;font-size:12px}input[type=file]{position:absolute;width:1px;height:1px;opacity:0}input[type=file]:focus-visible+.choose,button:focus-visible,a:focus-visible{outline:2px solid #438dc1;outline-offset:2px}.transfer{padding:10px 26px;border-top:1px solid #e1e7ec;background:#fafbfc}progress{width:200px;max-width:100%;accent-color:#1474b3}#status{display:inline-block;margin:0 0 0 8px;color:#60788a;overflow-wrap:anywhere}footer{padding:10px 26px;background:#fafbfc;color:#8d9aa4;font-size:12px;border-top:1px solid #e1e7ec}@media(max-width:650px){.topbar{padding:10px 12px}.topbar h1{font-size:15px}.address{font-size:12px}.toolbar{padding:10px 12px;flex-wrap:wrap}.upload-info{width:100%;margin:0}.layout{grid-template-columns:1fr;grid-template-rows:auto 1fr}.sidebar{border-right:0;border-bottom:1px solid #d8e0e7;padding:10px 12px}.sidebar h2{display:none}.selected{padding:8px 10px}.content{padding:18px 12px}.columns{grid-template-columns:minmax(0,1fr) 72px 40px}.details{grid-template-columns:minmax(0,1fr) 72px}.file{padding:10px 6px}.transfer,footer{padding:10px 12px}}
</style></head><body><main><header class="topbar"><h1>文件管理</h1><div class="address">共享目录 / 文件</div></header><div class="toolbar"><input id="file" type="file"><label class="choose" for="file">上传文件</label><button id="refresh">刷新</button><span class="upload-info">单个文件最大 <span id="limit"></span> · 同名文件不会被覆盖</span></div><div class="layout"><aside class="sidebar"><h2>位置</h2><div class="selected">▾ &nbsp;共享目录</div></aside><section class="content"><div class="heading"><h2>共享文件</h2><span class="badge" id="count"></span></div><div class="columns"><span>文件名</span><span>大小</span><span></span></div><div id="list" class="muted">正在加载文件…</div></section></div><div class="transfer"><progress id="progress" max="100" value="0" hidden></progress><p id="status" role="status" aria-live="polite"></p></div><footer>文件存储在服务器配置的共享目录中</footer></main>
<script>
const list=document.getElementById('list'),count=document.getElementById('count'),input=document.getElementById('file'),status=document.getElementById('status'),progress=document.getElementById('progress');
const maxUpload=__MAX_UPLOAD_BYTES__;
function formatSize(n){if(n<1024)return n+' B';let i=0,u=['KiB','MiB','GiB','TiB'];do{n/=1024;i++}while(n>=1024&&i<u.length);return n.toFixed(n<10?1:0)+' '+u[i-1]}
async function refresh(){list.textContent='正在加载文件…';count.textContent='';try{const r=await fetch('/api/files',{cache:'no-store'});if(!r.ok)throw Error('服务器返回 '+r.status);const files=await r.json();list.replaceChildren();list.className='';count.textContent=files.length+' 个文件';if(!files.length){list.className='muted';list.textContent='暂无文件，上传一个文件开始使用。';return}for(const f of files){const row=document.createElement('div');row.className='file';const icon=document.createElement('span');icon.className='icon';icon.textContent='▤';icon.setAttribute('aria-hidden','true');const detail=document.createElement('div');detail.className='details';const name=document.createElement('div');name.className='name';name.textContent=f.name;const size=document.createElement('div');size.className='size';size.textContent=formatSize(f.size);detail.append(name,size);const link=document.createElement('a');link.className='download';link.textContent='下载';link.href='/files/'+encodeURIComponent(f.name);link.setAttribute('download',f.name);row.append(icon,detail,link);list.append(row)}}catch(e){list.className='muted';list.textContent='加载失败：'+e.message}}
document.getElementById('limit').textContent=formatSize(maxUpload);
input.addEventListener('change',()=>{const f=input.files[0];if(!f)return;if(f.size>maxUpload){status.textContent='文件超过 '+formatSize(maxUpload)+' 上限。';input.value='';return}const xhr=new XMLHttpRequest();xhr.open('PUT','/files/'+encodeURIComponent(f.name));progress.hidden=false;progress.value=0;input.disabled=true;status.textContent='正在上传 '+f.name;xhr.upload.onprogress=e=>{if(e.lengthComputable)progress.value=e.loaded/e.total*100};xhr.onload=()=>{input.disabled=false;input.value='';if(xhr.status===201){status.textContent='上传成功：'+f.name;refresh()}else status.textContent=xhr.status===409?'上传失败：已存在同名文件。':xhr.status===413?'上传失败：文件超过大小上限。':'上传失败：服务器返回 '+xhr.status};xhr.onerror=()=>{input.disabled=false;input.value='';status.textContent='上传失败：网络连接异常。'};xhr.send(f)});document.getElementById('refresh').addEventListener('click',refresh);refresh();
</script></body></html>)PAGE";
